from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
ws=wb['Task']
# Data layout determined by inspection:
# series codes: Data!$D$21:$D$38
# year headers: Data!$H$4:$L$4
# values:       Data!$H$21:$L$38
lookup_blocks = [(12,17), (19,24), (26,31)]
for start,end in lookup_blocks:
    for r in range(start,end+1):
        for c in range(8,13):
            col=get_column_letter(c)
            ws.cell(r,c).value = f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'
# Net capacity headroom H35:L40
for i in range(6):
    r=35+i
    for c in range(8,13):
        col=get_column_letter(c)
        ws.cell(r,c).value = f'=({col}{12+i}-{col}{19+i})/{col}{26+i}*100'
# Summary stats H42:L47, order confirmed from column E labels
summary_by_label = {
    'minimum': 'MIN',
    'maximum': 'MAX',
    'median': 'MEDIAN',
    'simple mean': 'AVERAGE',
    'mean': 'AVERAGE',
    '25th percentile': 'PERCENTILE25',
    '75th percentile': 'PERCENTILE75',
}
for r in range(42,48):
    label = str(ws.cell(r,5).value or ws.cell(r,4).value or ws.cell(r,7).value or '').strip().lower()
    for c in range(8,13):
        col=get_column_letter(c)
        if label == 'minimum':
            formula=f'=MIN({col}35:{col}40)'
        elif label == 'maximum':
            formula=f'=MAX({col}35:{col}40)'
        elif label == 'median':
            formula=f'=MEDIAN({col}35:{col}40)'
        elif label in ('simple mean','mean'):
            formula=f'=AVERAGE({col}35:{col}40)'
        elif label == '25th percentile':
            formula=f'=PERCENTILE({col}35:{col}40,0.25)'
        elif label == '75th percentile':
            formula=f'=PERCENTILE({col}35:{col}40,0.75)'
        else:
            raise ValueError(f'Unexpected summary label on row {r}: {label!r}')
        ws.cell(r,c).value = formula
# Weighted mean H50:L50
for c in range(8,13):
    col=get_column_letter(c)
    ws.cell(50,c).value = f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)'
wb.save(path)
print('Saved formulas to', path)
print('Sheets after save:', wb.sheetnames)
